using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CityBridgeAccentBuild{
static CityBridgeAccentBuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityBridgeAccent.request"))return;File.Delete("CityBridgeAccent.request");try{Build();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BridgeAccents.txt",e.ToString());Debug.LogException(e);}}
class Buffer{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> ix=new List<int>();public void Strip(Vector3 a,Vector3 b,Vector3 across,float width,int color){if((b-a).sqrMagnitude<.01f)return;var s=across.normalized*width*.5f;int n=p.Count;p.AddRange(new[]{a-s,a+s,b+s,b-s});uv.AddRange(Enumerable.Repeat(new Vector2(64.25f+color,0),4));ix.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}}
static string Dir="Assets/Scenes/Oasis/BridgeLighting/LED Meshes";
static Mesh Save(Buffer b,string name){var m=new Mesh{name=name,indexFormat=b.p.Count>65535?IndexFormat.UInt32:IndexFormat.UInt16};m.SetVertices(b.p);m.SetUVs(0,b.uv);m.SetTriangles(b.ix,0);m.RecalculateNormals();m.RecalculateBounds();string path=Dir+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.indexFormat=m.indexFormat;old.SetVertices(b.p);old.SetUVs(0,b.uv);old.SetTriangles(b.ix,0);old.RecalculateNormals();old.RecalculateBounds();old.UploadMeshData(false);UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(m,path);return m;}
static MeshRenderer Add(MeshFilter f,Buffer b,Material material){var old=f.transform.Find("Mobile bridge LED strips");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var go=new GameObject("Mobile bridge LED strips");go.transform.SetParent(f.transform,false);go.layer=f.gameObject.layer;go.AddComponent<MeshFilter>().sharedMesh=Save(b,f.sharedMesh.name.Replace("/","_")+" LEDs");var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=material;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.forceRenderingOff=false;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;r.motionVectorGenerationMode=MotionVectorGenerationMode.ForceNoMotion;GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.OccludeeStatic);return r;}
static Buffer PortalBuffer(MeshFilter f){
var data=typeof(FinalPathwayRepair).GetMethod("Read",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,new object[]{f.sharedMesh});var ty=data.GetType();var v=(Vector3[])ty.GetField("p").GetValue(data);var ix=(int[])ty.GetField("ids").GetValue(data);var world=v.Select(f.transform.TransformPoint).ToArray();var parent=Enumerable.Range(0,v.Length).ToArray();Func<int,int> find=null;find=i=>parent[i]==i?i:(parent[i]=find(parent[i]));Action<int,int> join=(a,b)=>parent[find(a)]=find(b);var weld=new Dictionary<Vector3,int>();for(int i=0;i<v.Length;i++){var p=new Vector3(Mathf.Round(v[i].x*100),Mathf.Round(v[i].y*100),Mathf.Round(v[i].z*100));if(weld.ContainsKey(p))join(i,weld[p]);else weld[p]=i;}for(int i=0;i<ix.Length;i+=3){join(ix[i],ix[i+1]);join(ix[i],ix[i+2]);}
var output=new Buffer();int frame=0;float deck=f.GetComponent<Renderer>().bounds.min.y+f.GetComponent<Renderer>().bounds.size.y*.52f;
Action<Vector3,Vector3,Vector3,float,int> strip=(a,b,side,width,color)=>{var sa=f.transform.InverseTransformVector(side.normalized*width);output.Strip(f.transform.InverseTransformPoint(a),f.transform.InverseTransformPoint(b),sa,sa.magnitude,color);};
foreach(var group in Enumerable.Range(0,v.Length).GroupBy(find).Where(g=>g.Count()>800).OrderBy(g=>world[g.First()].x)){
var members=new HashSet<int>(group);var positions=new List<Vector3>();for(int k=0;k<ix.Length;k+=3){if(!members.Contains(ix[k]))continue;for(int j=0;j<3;j++){var a=world[ix[k+j]];var b=world[ix[k+(j+1)%3]];if(Mathf.Abs(a.y-b.y)<2||new Vector2(a.x-b.x,a.z-b.z).magnitude>.06f)continue;positions.Add(a);positions.Add(b);}}
var clusters=new List<List<Vector3>>();foreach(var p in positions){var list=clusters.FirstOrDefault(g=>new Vector2(g[0].x-p.x,g[0].z-p.z).magnitude<5);if(list==null){list=new List<Vector3>();clusters.Add(list);}list.Add(p);}var posts=clusters.Where(g=>g.Max(p=>p.y)-g.Min(p=>p.y)>50).OrderByDescending(g=>g.Count).Take(2).ToArray();if(posts.Length!=2)throw new Exception("Cannot resolve portal pillars "+frame+" clusters="+clusters.Count);
var centers=posts.Select(g=>g.Aggregate(Vector3.zero,(a,p)=>a+p)/g.Count).ToArray();var cross=centers[1]-centers[0];cross.y=0;cross.Normalize();var road=Vector3.Cross(Vector3.up,cross).normalized;float top=posts.Min(g=>g.Max(p=>p.y));
for(int p=0;p<2;p++){var center=centers[p];float bottom=Mathf.Max(deck,posts[p].Min(q=>q.y));foreach(int side in new[]{-1,1}){var face=road*side;float extent=posts[p].Max(q=>Vector3.Dot(q-center,face));var anchor=center+face*(extent+.025f);strip(new Vector3(anchor.x,bottom+.12f,anchor.z),new Vector3(anchor.x,top-.15f,anchor.z),cross,.24f,(frame+p)%2);}}
frame++;}
if(frame==0)throw new Exception("No bridge portal frames found");return output;}

static void Build(){var sc=SceneManager.GetActiveScene();Directory.CreateDirectory(Dir);Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeBridgeLEDs");if(!File.Exists("FinalEnvironmentRoadBackup/BeforeBridgeLEDs/Scene.unity"))EditorSceneManager.SaveScene(sc,"FinalEnvironmentRoadBackup/BeforeBridgeLEDs/Scene.unity",true);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/BridgeLighting/Bridge Night.mat");material.shader=Shader.Find("Gangstar City/Bridge Night Lit");AssetDatabase.ImportAsset(AssetDatabase.GetAssetPath(material.shader),ImportAssetOptions.ForceUpdate);if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Bridge shader compilation failed");int lights=sc.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length);var filters=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh&&AssetDatabase.GetAssetPath(f.sharedMesh).Contains("/BridgeStructures/")&&f.sharedMesh.name.Contains("Metal")).ToArray();var added=new Dictionary<Renderer,Renderer>();int total=0;var log=new System.Text.StringBuilder();foreach(var f in filters){var mesh=f.sharedMesh;var v=mesh.vertices;var uv=mesh.uv;var b=new Buffer();var tris=mesh.triangles;for(int ti=0;ti+5<tris.Length;ti+=3){int k=tris[ti];if(k+3>=v.Length||k+3>=uv.Length)continue;if(tris[ti+1]!=k+1||tris[ti+2]!=k+2||tris[ti+3]!=k||tris[ti+4]!=k+2||tris[ti+5]!=k+3)continue;ti+=3;float width=Vector3.Distance(v[k],v[k+1]),len=Vector3.Distance(v[k+1],v[k+2]);if(len<1||len<width*1.8f||width>.0f&&width>2f)continue;int face=Mathf.RoundToInt(uv[k].x);bool cable=width<.3f;if(!cable&&face!=1&&face!=3)continue;if(cable&&k%2!=0)continue;if(cable&&!mesh.name.Contains("Bridge_1_")){var delta=f.transform.TransformVector((v[k+2]+v[k+3]-v[k]-v[k+1])*.5f);if(new Vector2(delta.x,delta.z).magnitude>Mathf.Abs(delta.y)*.12f)continue;}var across=(v[k+1]-v[k]).normalized;var acrossEnd=(v[k+2]-v[k+3]).normalized;var normal=Vector3.Cross(v[k+1]-v[k],v[k+2]-v[k]).normalized;Vector3 a=(v[k]+v[k+1])*.5f+normal*.08f,bb=(v[k+2]+v[k+3])*.5f+normal*.08f;if(cable)b.Strip(a,bb,across,.065f,2);else{b.Strip(a-across*width*.28f,bb-acrossEnd*width*.28f,across,.22f,0);b.Strip(a+across*width*.28f,bb+acrossEnd*width*.28f,across,.22f,Mathf.FloorToInt(Mathf.Abs(uv[k].y)/10f)%2);}}if(b.ix.Count==0)continue;var r=Add(f,b,material);added[f.GetComponent<Renderer>()]=r;total+=b.ix.Count/3;log.AppendLine(f.name+" "+f.sharedMesh.name+" strips="+b.p.Count/4+" triangles="+b.ix.Count/3);}
// Original bridge: clean continuous portal face strips, measured in world units.
var original=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).FirstOrDefault(f=>f.name=="bridge");if(original){var b=PortalBuffer(original);var rr=Add(original,b,material);added[original.GetComponent<Renderer>()]=rr;total+=b.ix.Count/3;log.AppendLine("Original bridge clean portal strips="+b.p.Count/4+" triangles="+b.ix.Count/3);}
foreach(var lod in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true))){var levels=lod.GetLODs();bool changed=false;for(int i=0;i<levels.Length;i++){var extra=levels[i].renderers.Where(r=>r&&added.ContainsKey(r)).Select(r=>added[r]).ToArray();if(extra.Length==0)continue;levels[i].renderers=levels[i].renderers.Where(r=>r&&r.name!="Mobile bridge LED strips").Concat(extra).ToArray();changed=true;}if(changed){lod.SetLODs(levels);EditorUtility.SetDirty(lod);}}
material.SetShaderPassEnabled("GBuffer",true);material.SetShaderPassEnabled("MobileLED",true);material.SetShaderPassEnabled("UniversalForwardOnly",true);material.enableInstancing=true;EditorUtility.SetDirty(material);AssetDatabase.SaveAssets();if(ShaderUtil.ShaderHasError(material.shader)||lights!=sc.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length))throw new Exception("Bridge validation failed");EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);var c=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=c.IsNight;try{c.Apply(true);log.AppendLine("Night="+Shader.GetGlobalFloat("_GangstarNight")+" pipeline="+GraphicsSettings.currentRenderPipeline+" material shader="+material.shader.name+" pass="+material.FindPass("MobileLED"));foreach(var rr in added.Values)log.AppendLine("LED="+rr.name+" enabled="+rr.enabled+" active="+rr.gameObject.activeInHierarchy+" bounds="+rr.bounds);var cap=typeof(CityTaxiStandBuild).GetMethod("Capture",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);var chosen=filters.First(f=>f.sharedMesh.name.Contains("Bridge_3_Metal_LOD0"));var bound=chosen.GetComponent<Renderer>().bounds;if(original){cap.Invoke(null,new object[]{sc,new Vector3(850,68,-490),new Vector3(720,64,-675),"Bridge-Portal-Corrected"});}cap.Invoke(null,new object[]{sc,bound.center+new Vector3(45,9,85),bound.center,"Bridge-LED-Night"});c.Apply(false);cap.Invoke(null,new object[]{sc,bound.center+new Vector3(45,9,85),bound.center,"Bridge-LED-Day"});}finally{foreach(var gg in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true)))gg.ForceLOD(-1);c.Apply(night);}File.WriteAllText("FinalEnvironmentRoadReview/BridgeAccents.txt","SUCCESS. Existing structures, materials and textures retained. Added thin blue/amber arch strips and cool cable accents, same existing Bridge Night material, no real-time lights, no textures sampled by LED fragment path, LOD-linked generated bridges, source meshes/colliders unchanged. Shader errors=0. Added triangles including all LOD levels="+total+"; scene lights unchanged="+lights+". Android timing unmeasured.\n"+log);}
}





















